/**
 * 小手机（悬浮窗）：主屏＋四个应用——短信 / 画廊 / 成就 / 笔记
 *
 * 为什么是后台脚本：悬浮窗要浮在酒馆整页之上，而状态栏是消息楼层里的 iframe，
 * 它的"固定定位"只能固定在自己的小框里。所以把启动胶囊和窗口挂到酒馆父页面。
 *
 * 约定：正文不提手机；手机内容不进主聊天、不进 stat_data。
 * 对局进行中：整机只读——四个应用都能翻看，但不能发消息、不能改笔记。
 */

const 前缀 = 'jgcell';
const 记录键 = '酒鬼手机记录';
const 笔记键 = '酒鬼手机笔记';
const 画廊键 = '酒鬼手机画廊';
const 记录上限 = 60;
const 图床 = 'https://enitiyfiaz.github.io/jiugui-card/portrait/';
const CG床 = 'https://enitiyfiaz.github.io/jiugui-card/cg/';

/** 情绪对应的头像文件名（画廊第一页用同一套） */
function 立绘文件(情绪: string): string {
  if (情绪 === '低迷') return 'gloomy.png';
  if (情绪 === '狂暴') return 'rage.png';
  if (情绪 === '痴迷') return 'obsessed.png';
  return 'base.png';
}

interface 手机短信 {
  我方: boolean;
  文: string;
  时间: number;
}

/* ── 变量读写（都走聊天级，跨楼层保留） ── */

function 读聊天(): Record<string, any> {
  try {
    return (getVariables({ type: 'chat' }) || {}) as Record<string, any>;
  } catch {
    return {};
  }
}

async function 写聊天(键: string, 值: unknown): Promise<void> {
  try {
    await insertOrAssignVariables({ [键]: 值 }, { type: 'chat' });
  } catch {
    /* 写失败也保留内存状态 */
  }
}

function 读记录(): 手机短信[] {
  const 原 = 读聊天()[记录键];
  if (!Array.isArray(原)) return [];
  return 原
    .filter((x: any) => x && typeof x.文 === 'string' && x.文.length > 0)
    .map((x: any) => ({ 我方: x.我方 === true, 文: String(x.文), 时间: Number(x.时间) || Date.now() }));
}

/* ── 局势读取（从变量读，不猜接口） ── */

interface 局势 {
  占有度: number;
  情绪: string;
  奖励次数: number;
  对局状态: string;
  轮数: number;
}

function 读局势(): 局势 {
  const 默认: 局势 = { 占有度: 0, 情绪: '痴迷', 奖励次数: 0, 对局状态: '', 轮数: 0 };
  try {
    const 聊天 = 读聊天();
    const 快照 = 聊天.酒鬼对局状态;
    if (快照?.灵魂 || 快照?.对局) {
      return {
        占有度: Number(快照.灵魂?.占有度) || 0,
        情绪: String(快照.灵魂?.情绪 ?? '痴迷'),
        奖励次数: Number(快照.灵魂?.奖励次数) || 0,
        对局状态: String(快照.对局?.状态 ?? ''),
        轮数: Number(快照.对局?.轮数) || 0,
      };
    }
    for (let i = 0; i <= 8; i++) {
      const 变量: any = getVariables(i === 0 ? { type: 'message' } : { type: 'message', message_id: -i }) || {};
      const 灵魂 = 变量?.stat_data?.灵魂;
      if (灵魂) {
        return {
          占有度: Number(灵魂.占有度) || 0,
          情绪: String(灵魂.情绪 ?? '痴迷'),
          奖励次数: Number(灵魂.奖励次数) || 0,
          对局状态: String(变量?.stat_data?.对局?.状态 ?? ''),
          轮数: Number(变量?.stat_data?.对局?.轮数) || 0,
        };
      }
    }
  } catch {
    /* 读不到用默认 */
  }
  return 默认;
}

/* ── 宿主窗口：脚本可能跑在酒馆助手的 iframe 里 ──
 * jQuery 在酒馆助手脚本里是作用到父页面的，但裸 document 未必是父页面；
 * 悬浮窗要浮在酒馆界面上，所以这里显式取父页面文档，取不到才退回自己。 */

function 取宿主(): Document {
  try {
    const 父 = (window as any).parent as Window | undefined;
    if (父 && 父 !== window && 父.document?.body) return 父.document;
  } catch {
    /* 跨域等情况退回自己 */
  }
  return document;
}

/** 是不是本卡的聊天：先看角色名，再看本卡变量 */
function 是本卡(): boolean {
  try {
    const 上下文 = (window as any).parent?.SillyTavern?.getContext?.() ?? (window as any).SillyTavern?.getContext?.();
    const 号 = 上下文?.characterId ?? 上下文?.this_chid;
    const 名 = 号 !== undefined && 号 !== null ? 上下文?.characters?.[号]?.name : '';
    if (typeof 名 === 'string' && 名.includes('酒鬼')) return true;
  } catch {
    /* 拿不到角色名就靠变量判断 */
  }
  try {
    const 聊天 = 读聊天();
    if ('酒鬼开场已读' in 聊天 || 记录键 in 聊天 || 笔记键 in 聊天 || 画廊键 in 聊天) return true;
    for (let i = 0; i <= 8; i++) {
      const 变量: any = getVariables(i === 0 ? { type: 'message' } : { type: 'message', message_id: -i }) || {};
      if (变量?.stat_data?.对局 || 变量?.stat_data?.灵魂) return true;
    }
  } catch {
    /* 当作不是 */
  }
  return false;
}

/* ── 她的短信口吻 ── */

function 提示词(玩家消息: string, 近况: 手机短信[], 局势: 局势): string {
  const 来往 = 近况
    .slice(-6)
    .map(m => `${m.我方 ? '达令' : '我'}：${m.文}`)
    .join('\n');
  return [
    '你正在用手机给达令发一条短信。',
    '你是梵·醺儿：酒的恶魔，病态地痴情，把占有当成爱；说话像谈情说爱，哪怕说的事情会要命，也说得像一件值得期待的事。称对方「达令」，尾音拖得绵软；情绪会在亢奋与低迷之间摇摆，亢奋时语无伦次，低迷时只剩呢喃。',
    `此刻：灵魂占有度 ${局势.占有度}%，情绪「${局势.情绪}」，她已经赢下达令 ${局势.奖励次数} 次。`,
    '要求：只输出短信正文本身，一到两句，短句、口语，像真的在手机上打字；不要旁白、不要动作描写、不要引号、不要时间戳、不要写自己的名字。',
    来往 ? `之前的来往：\n${来往}` : '',
    `达令刚发来的消息：${玩家消息}`,
  ]
    .filter(Boolean)
    .join('\n');
}

async function 请她回信(玩家消息: string, 近况: 手机短信[]): Promise<string | null> {
  try {
    const 回 = await generate({ user_input: 提示词(玩家消息, 近况, 读局势()), should_silence: true, max_chat_history: 4 });
    if (typeof 回 !== 'string') return null;
    const 文 = 回
      .trim()
      .replace(/^[「『"“']+|[」』"”']+$/g, '')
      .trim();
    return 文.length > 0 ? 文 : null;
  } catch {
    return null;
  }
}

