function 读画廊(): string[] {
  const 原 = 读聊天()[画廊键];
  return Array.isArray(原) ? 原.filter((x: any) => typeof x === 'string') : [];
}

function 画解锁(局势: 局势, 已见: string[]): Record<string, boolean> {
  return {
    base: true,
    obsessed: 已见.includes('痴迷') || 局势.情绪 === '痴迷',
    gloomy: 已见.includes('低迷') || 局势.情绪 === '低迷',
    rage: 已见.includes('狂暴') || 局势.情绪 === '狂暴',
    end: 局势.占有度 >= 100 || 局势.对局状态 === '终局',
  };
}

